import React, { createContext, useState, useEffect, useContext } from 'react';

export const AuthContext = createContext(null);

export const AuthProvider = ({ children }) =>
    { const [user, setUser] = useState(null); 
      const [loading, setLoading] = useState(true);

    const checkAuth = async () => 
        { 
            try { const res = await fetch('/api/me/', { credentials: 'include' }); 
                if (res.ok) { const data = await res.json(); setUser(data); } 
                else { setUser(null); } } 
                
            catch (e) { setUser(null); } 
            finally { setLoading(false); } 
        };

    useEffect(() => { checkAuth(); }, []);

    //function getCookie(name) {
    //     const cookies = document.cookie.split(';');
    //     for (let cookie of cookies) {
    //         const [key, value] = cookie.trim().split('=');
    //         if (key === name) {
    //         return decodeURIComponent(value);
    //         }
    //     }
    //     return null;
    // }

    function getCookie(name) { 
        const value = `; ${document.cookie}`; 
        const parts = value.split(`; ${name}=`); 
        if (parts.length === 2) {
            const cookieValue = parts.pop().split(';').shift();
            return cookieValue ? decodeURIComponent(cookieValue) : '';
        }     
        return ""; 
    }

    async function ensureCsrfToken() {
        return fetch('http://localhost:8000/api/get_csrf_token/', { method: 'GET', credentials: 'include' }) 
        .then(res => { if (!res.ok) throw new Error(`HTTP error! status: ${res.status}`); return res.json(); }) 
        .then(data => data.csrf_token);
    }

    const login = async (username, password) => 

        {
            await ensureCsrfToken();
            const csrfToken = getCookie('csrftoken');
            const resp = await fetch('http://localhost:8000/api/login/', { 
                method: 'POST', 
                headers: { 'Content-Type': 'application/json', 'X-CSRFToken': csrfToken }, 
                credentials: 'include', body: JSON.stringify({ username, password }) 
            });
            if (resp.ok) { await checkAuth(); return true; } 
            return false;
        };

    const logout = async () => 
        { 
            await fetch('/api/logout/', { method: 'POST', credentials: 'include' }); 
            setUser(null); 

        };

    return ( 
        <AuthContext.Provider value={{ user, loading, login, logout, isAuthenticated: !!user }}> 
        {children} </AuthContext.Provider> 
        ); 

    };

export const useAuth = () => useContext(AuthContext);
